const trophyIcon='<svg viewBox="0 0 80 88" fill="none" aria-hidden="true"><path d="M22 12h36v21c0 16-9 26-18 26S22 49 22 33V12Z" stroke="currentColor" stroke-width="3"/><path d="M22 19H10v12c0 12 8 18 16 18m32-30h12v12c0 12-8 18-16 18M40 59v16m-14 0h28m-31 8h34" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><path d="m40 23 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z" fill="currentColor"/></svg>';
function cupOutcome(){if(state?.phase!=='full')return null;return season.competition==='europe'?Europe.preview(season,state):season.competition==='cup'?P.preview(season,state):null;}
function cupKicks(result){if(!result?.penalties)return '';const order=result.home===S.own?[0,1]:[1,0],ownScore=order.map(i=>result.penalties[i]);return '<div class="penalty-report"><div><div class="eyebrow">PENALTY SHOOTOUT</div><h3>승부차기 '+ownScore[0]+' : '+ownScore[1]+'</h3><p>90분 무승부 뒤 승부차기로 진출 구단을 결정했습니다.</p></div><div class="penalty-teams">'+order.map(i=>'<div><b>'+S.club(i===0?result.home:result.away).short+'</b><span class="penalty-kicks">'+result.kicks[i].map((goal,k)=>'<i class="'+(goal?'scored':'missed')+'" aria-label="'+(k+1)+'번째 '+(goal?'성공':'실패')+'">'+(goal?'●':'×')+'</i>').join('')+'</span></div>').join('')+'</div></div>';}
function cupStatus(){const c=season.cup,ownResults=c.results.filter(r=>r.home===S.own||r.away===S.own),lost=ownResults.find(r=>r.winner!==S.own);if(!c.enabled)return '다음 시즌부터 참가';if(c.champion)return S.club(c.champion).short+' 우승';if(lost)return P.stageName(season,lost.stage)+'에서 도전 마무리';if(season.competition==='cup')return P.stageName(season,c.stage)+(state?.phase==='full'?' · 결과 확정 대기':state?.phase==='prep'?' · 지금 경기 준비':' · 경기 진행 중');return '리그 '+P.gateFor(season)+'경기 뒤 '+P.stageName(season,c.stage);}
function cupRecords(){const records=season.history.map(h=>({...h})),rounds=S.leagueRoundCount(season),finished=season.round===rounds;if(finished||season.cup.champion){const table=S.standings(season),me=table.find(c=>c.id===S.own);records.push({year:season.year,division:season.league.division,rules:season.league.rules,nextDivision:finished?S.movement(season).to:season.league.division,rank:finished?me.rank:null,points:finished?me.points:null,champion:finished?table[0].id:null,cupChampion:season.cup.champion,pending:!S.ready(season)});}return records;}
function renderCup(){
 if(typeof view!=='undefined'&&view!=='club'&&view!=='cup')return;
 const cup=season.cup,status=cupStatus(),tier=S.divisionInfo(season),ownClub=S.club(S.own);
 if(typeof view==='undefined'||view==='club'){
 $('cup-summary').innerHTML='<div class="cup-band"><span class="cup-mini-icon">'+trophyIcon+'</span><div><span>'+tier.cupName+'</span><strong>'+status+'</strong></div><button id="open-cup" class="text-button">대진과 우승 기록 →</button></div>';$('open-cup').onclick=()=>setView('cup');
 }
 if(typeof view!=='undefined'&&view!=='cup')return;
 const ownResults=cup.results.filter(r=>r.home===S.own||r.away===S.own),lost=ownResults.find(r=>r.winner!==S.own),active=season.competition==='cup'&&!!state,records=cupRecords(),leagueTitles=records.filter(r=>r.division===1&&r.champion===S.own).length,lowerTitles=records.filter(r=>(r.rules==='five-tier'?r.division>1:r.division===2)&&r.champion===S.own).length,cupTitles=records.filter(r=>r.cupChampion===S.own).length,promotions=records.filter(r=>r.rules==='five-tier'?r.nextDivision<r.division:r.division===2&&r.nextDivision===1).length,rates=E.rates(season);
 const stageCount=P.stageCount(season),clubCount=S.leagueClubs(season).length,roundCount=S.leagueRoundCount(season),stages=Array.from({length:stageCount},(_,i)=>P.stageName(season,i)),gates=Array.from({length:stageCount},(_,i)=>P.gateFor(season,i));
 const description=!cup.enabled?'진행하던 시즌을 마치고 다음 시즌부터 컵에 참가합니다.':cup.champion?(cup.champion===S.own?'최대 '+stageCount+'라운드를 거쳐 우리 구단이 마지막에 남긴 이름.':'이번 컵의 우승 구단은 '+S.club(cup.champion).name+'입니다.'):lost?'이번 컵 도전은 끝났습니다. 남은 리그에서 다음 기회를 준비하세요.':'리그 사이에 최대 '+stageCount+'라운드로 이어지는 단판 승부.<br>90분에 비기면 승부차기로 다음 라운드 진출을 가립니다.';
 $('cup-overview').innerHTML='<div class="cup-hero"><div><div class="eyebrow">'+tier.cupEn+' / SEASON '+String(season.year).padStart(2,'0')+'</div><h1>'+(cup.champion===S.own?'우리의 이름을 새겼다.':'한 경기로 달라지는 시즌.')+'</h1><p>'+description+'</p><span class="cup-state">'+status+'</span>'+(active?'<button id="cup-match" class="primary">'+P.stageName(season,cup.stage)+' '+(state.phase==='full'?'결과 확인':'경기 준비하기')+'</button>':'')+'</div><div class="cup-emblem">'+trophyIcon+'<span>'+tier.cupEn.split(' ').join('<br>')+'</span></div></div><div class="cup-rules"><div><b>'+stages.join(' → ')+'</b><span>'+tier.division+'부 '+clubCount+'개 구단 단판 토너먼트<br>리그 '+gates.join(' · ')+'경기 뒤 진행</span></div><div><b>90분 + 승부차기</b><span>연장전 없이 한 경기로 결정<br>교체 3명 · 출전 경험 반영</span></div><div><b>진출할수록 더 큰 상금</b><span>초반 승리 '+moneyLabel(rates.cupBonuses[0])+' · 준결승 '+moneyLabel(rates.cupBonuses[Math.max(0,stageCount-2)])+'<br>우승 '+moneyLabel(rates.cupBonuses[stageCount-1])+' + 홈 / 원정 수입</span></div></div>';
 if(active)$('cup-match').onclick=()=>setView('match');
 $('cup-bracket').innerHTML='<div class="panel-heading"><h2>우승까지의 길</h2><span>'+tier.division+'부 구단 '+clubCount+'팀 · 단판 토너먼트</span></div><div class="cup-tree">'+Array.from({length:stageCount},(_,stage)=>{const name=stages[stage],fixtures=P.fixturesFor(season,stage),count=fixtures.length||(stageCount===3?[4,2,1][stage]:stage===0?(clubCount===20?4:8):[0,8,4,2,1][stage]);return '<section class="cup-stage"><div class="cup-stage-heading"><h3>'+name+'</h3><span>리그 '+P.gateFor(season,stage)+'경기 뒤</span></div><div class="cup-stage-games">'+Array.from({length:count},(_,index)=>{const fixture=fixtures[index],result=cup.results.find(r=>r.stage===stage&&r.index===index),current=active&&stage===cup.stage&&(fixture?.home===S.own||fixture?.away===S.own);return '<article class="cup-pair '+(current?'cup-current':'')+'" aria-label="'+name+' '+(index+1)+'경기"><div class="cup-pair-state">'+(result?'결과 확정':current?'우리의 다음 경기':'경기 '+(index+1))+'</div>'+[0,1].map(i=>{const id=fixture?.[i===0?'home':'away'],club=id?S.club(id):null;return '<div class="cup-team '+(result&&club?.id===result.winner?'winner':'')+'">'+(club?clubMark(club):'<span class="club-mark unknown">?</span>')+'<span>'+(club?club.short:(stage?P.stageName(season,stage-1):'예선')+' '+(index*2+i+1)+'경기 승자')+'</span><b>'+(result?result.goals[i]:'—')+'</b></div>';}).join('')+(result?.penalties?'<p class="cup-pair-note">승부차기 '+result.penalties.join(' : ')+'</p>':'')+'</article>';}).join('')+'</div></section>';}).join('')+'</div><p class="finance-note">'+tier.cupName+' 경기 수입은 홈 '+moneyLabel(rates.cupHome)+' / 원정 '+moneyLabel(rates.cupAway)+'입니다. 컵에서는 별도 주간 급여를 지급하지 않습니다. 경기 뒤 체력 20 회복 · 다음 리그 준비 때 훈련과 영입 가능.</p>';
 if(!cup.enabled)$('cup-bracket').innerHTML='<div class="trophy-empty">이번 시즌은 진행하던 리그만 마칩니다. 다음 시즌부터 새 컵 대진과 함께 시작하세요.</div>';
 $('trophy-room').innerHTML='<div class="trophy-heading"><div><div class="eyebrow">THE TROPHY ROOM</div><h2>시즌이 끝나도 남는 것.</h2></div><span>'+ownClub.name+'의 우승 기록</span></div><div class="trophy-counts">'+[['1부 리그 우승',leagueTitles],[season.league.rules==='five-tier'?'하부 리그 우승':'2부 리그 우승',lowerTitles],['디비전 컵 우승',cupTitles],[season.league.rules==='five-tier'?'승격 횟수':'1부 승격',promotions]].map(([label,n])=>'<div class="trophy-count '+(n?'earned':'')+'"><span class="trophy-symbol">'+trophyIcon+'</span><div><span>'+label+'</span><strong>'+n+'<small>회</small></strong></div></div>').join('')+'</div>'+(records.length?'<div class="table-wrap"><table class="trophy-table"><thead><tr><th>시즌</th><th>리그 성적</th><th>리그 우승</th><th>컵 우승</th></tr></thead><tbody>'+records.map(r=>'<tr><th scope="row">'+r.year+'시즌<small>'+S.divisionInfo(r).name+' · '+r.division+'부'+(r.pending?' · 진행 중':'')+'</small>'+'</th><td>'+(r.rank?r.rank+'위 · '+r.points+'점<small>'+movementText(r)+'</small>':'진행 중')+'</td><td class="'+(r.champion===S.own?'title-own':'')+'">'+(r.champion?S.club(r.champion).short:'미정')+'</td><td class="'+(r.cupChampion===S.own?'title-own':'')+'">'+(r.cupChampion?S.club(r.cupChampion).short:r.year===season.year?(!cup.enabled?'이번 시즌 미참가':'진행 중'):'기록 없음')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="trophy-empty">첫 트로피를 기다리는 빈자리. 리그와 컵에서 우리 구단의 이름을 남겨보세요.</p>');
}
